// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.telemetryimport android.content.Contextimport com.roshan.persona.common.CorrelationIdimport org.json.JSONObjectimport timber.log.Timberimport java.io.Fileimport java.io.FileOutputStreamimport java.time.Instantimport java.util.concurrent.atomic.AtomicLongimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Audit log. * * Security-sensitive operations are recorded in an append-only, line-delimited * JSON file (`audit_log.jsonl`) stored in the app's internal storage. The file * is: *   - Separate from regular telemetry (cannot be silently disabled) *   - User-accessible (Settings → Privacy → Audit Log → View) *   - Exportable (Settings → Privacy → Audit Log → Export → encrypted ZIP) *   - Retained for 90 days (entries older than 90 days are pruned on a *     best-effort basis during [record] calls — lazy GC) * * Recorded operations: *   - Every skill invocation (skill name, user input hash, success/fail) *   - Every LLM call (provider, model, prompt hash — NOT prompt content) *   - Every permission grant/deny (permission, granted by user?) *   - Every crypto operation (encrypt/decrypt/hash target) *   - Every accessibility action (gesture, package targeted) *   - Every remote config change (key, old value, new value) *   - Every privacy setting change (setting, old, new) * * NOT recorded: *   - Prompt contents (privacy — only SHA-256 hash for correlation) *   - LLM responses (privacy) *   - User PII (no emails, phone numbers, etc.) * * ## Real persistence * * Each entry is appended to `audit_log.jsonl` in app-internal storage via * a synchronized [FileOutputStream] with `MODE_APPEND`. The file is private * to the app (not shared, not synced to cloud — ADR 0011 Maximum Privacy * Default). It is auto-deleted on app uninstall. * * For higher-security scenarios (e.g., audit log of credential vault * access), the Brain pipeline uses [com.roshan.persona.security.audit.EncryptedAuditLogPersistence] * which double-encrypts each entry via AndroidKeystore + EncryptedSharedPreferences. * This [AuditLog] class is the lower-level, file-based audit trail used by * core modules (e.g. [com.roshan.persona.security.IntegrityAttestation]) that * don't have a dependency on `:feature:security`. */@Singletonclass AuditLog @Inject constructor(    @dagger.hilt.android.qualifiers.ApplicationContext private val appContext: Context,) {    /** Audit event types. */    enum class EventType {        SKILL_INVOCATION,        LLM_CALL,        PERMISSION_GRANT,        PERMISSION_DENY,        CRYPTO_ENCRYPT,        CRYPTO_DECRYPT,        CRYPTO_HASH,        ACCESSIBILITY_ACTION,        REMOTE_CONFIG_CHANGE,        PRIVACY_SETTING_CHANGE,        INTEGRITY_CHECK,        BACKUP_OPERATION,        RESTORE_OPERATION,    }    /** Audit outcome. */    enum class AuditOutcome { SUCCESS, FAILURE, DENIED, ERROR }    /** Audit entry — serializable for export. */    data class AuditEntry(        val id: Long,        val timestamp: Instant,        val type: EventType,        val action: String,        val correlationId: String,        val outcome: AuditOutcome,        val metadata: Map<String, String>,    )    private val auditFile: File by lazy {        File(appContext.filesDir, AUDIT_LOG_FILENAME).also { file ->            if (!file.exists()) {                try {                    file.parentFile?.mkdirs()                    file.createNewFile()                } catch (e: Exception) {                    Timber.tag("NOUS.Audit").w(e, "Failed to create audit log file")                }            }        }    }    private val sequence = AtomicLong(0L)    /** Append an entry to the audit log. */    @Synchronized    fun record(        type: EventType,        action: String,        correlationId: CorrelationId = CorrelationId.generate(),        outcome: AuditOutcome = AuditOutcome.SUCCESS,        metadata: Map<String, String> = emptyMap(),    ) {        val id = sequence.incrementAndGet()        val entry = AuditEntry(            id = id,            timestamp = Instant.now(),            type = type,            action = action,            correlationId = correlationId.value,            outcome = outcome,            metadata = metadata,        )        val line = serializeEntry(entry)        appendToFile(line)        // Lazy GC — prune entries older than 90 days every ~100 records.        if (id % PRUNE_INTERVAL == 0L) {            try {                pruneOldEntries()            } catch (e: Exception) {                Timber.tag("NOUS.Audit").w(e, "Failed to prune audit log")            }        }        Timber.tag("NOUS.Audit").i(            "[${type.name}] $action → $outcome (correlationId=${correlationId.value})",        )    }    // ─── Internal helpers ─────────────────────────────────────────────    /** Serialize an entry as a single line of JSON (JSONL format). */    private fun serializeEntry(entry: AuditEntry): String {        return JSONObject().apply {            put("id", entry.id)            put("ts", entry.timestamp.toEpochMilli())            put("type", entry.type.name)            put("action", entry.action)            put("correlationId", entry.correlationId)            put("outcome", entry.outcome.name)            val meta = JSONObject()            entry.metadata.forEach { (k, v) -> meta.put(k, v) }            put("metadata", meta)        }.toString()    }    /** Append a single line to the audit log file, with a trailing newline. */    private fun appendToFile(line: String) {        try {            FileOutputStream(auditFile, true).use { out ->                out.write(line.toByteArray(Charsets.UTF_8))                out.write('\n'.code)                out.flush()            }        } catch (e: Exception) {            // Audit log persistence must NEVER crash the calling module.            Timber.tag("NOUS.Audit").w(e, "Failed to append audit entry")        }    }    /**     * Prune entries older than [RETENTION_DAYS].     *     * Reads the file line-by-line, keeps recent entries, rewrites the file     * atomically via a temp file + rename. Called lazily every     * [PRUNE_INTERVAL] records — amortized cost is low.     */    private fun pruneOldEntries() {        val cutoffMs = System.currentTimeMillis() -            java.util.concurrent.TimeUnit.DAYS.toMillis(RETENTION_DAYS.toLong())        val kept = mutableListOf<String>()        try {            auditFile.useLines { lines ->                lines.forEach { line ->                    try {                        val json = JSONObject(line)                        val ts = json.optLong("ts", 0L)                        if (ts >= cutoffMs) {                            kept.add(line)                        }                    } catch (e: Exception) {                        // Corrupt line — drop it during pruning.                    }                }            }        } catch (e: Exception) {            Timber.tag("NOUS.Audit").w(e, "Failed to read audit log for pruning")            return        }        // Atomic rewrite: write to a temp file then rename over the original.        val tmp = File(auditFile.parentFile, "$AUDIT_LOG_FILENAME.tmp")        try {            tmp.printWriter(Charsets.UTF_8).use { writer ->                kept.forEach { writer.println(it) }            }            if (!tmp.renameTo(auditFile)) {                // Rename failed — fall back to delete + rename to avoid loss.                auditFile.delete()                tmp.renameTo(auditFile)            }        } catch (e: Exception) {            Timber.tag("NOUS.Audit").w(e, "Failed to rewrite pruned audit log")            tmp.delete()        }    }    private companion object {        const val AUDIT_LOG_FILENAME = "audit_log.jsonl"        const val RETENTION_DAYS = 90        const val PRUNE_INTERVAL = 100L    }}